// Attendance service — tries API first, falls back to localStorage

class AttendanceService {
  constructor() {
    this.storageKey = "attendanceRecords";
  }

  // ── GET attendance records (filtered by studentId and/or date) ──
  async getAttendance(params = {}) {
    try {
      const response = await fetch(
        `http://localhost:5155/api/attendance?${new URLSearchParams(params)}`,
        {
          method:  "GET",
          headers: { "Content-Type": "application/json" },
        }
      );

      if (response.ok) {
        const data = await response.json();

        // Even if API succeeds, filter strictly by studentId on the frontend
        // so a misconfigured backend never leaks other students' records
        if (params.studentId !== undefined) {
          return Array.isArray(data)
            ? data.filter(r => String(r.studentId) === String(params.studentId))
            : [];
        }

        return Array.isArray(data) ? data : [];
      }
      throw new Error("API not available");
    } catch (error) {
      console.log("Using localStorage for attendance");
      return this.getLocalAttendance(params);
    }
  }

  // ── GET single attendance record for a student on a specific date ──
  async getAttendanceRecord(studentId, date) {
    try {
      const response = await fetch(
        `http://localhost:5155/api/attendance/${studentId}/${date}`,
        {
          method:  "GET",
          headers: { "Content-Type": "application/json" },
        }
      );

      if (response.ok) {
        const data = await response.json();

        // Verify returned record actually belongs to this student
        if (data && String(data.studentId) !== String(studentId)) {
          return null;
        }

        return data;
      }
      throw new Error("API not available");
    } catch (error) {
      console.log("Using localStorage for attendance record");
      return this.getLocalAttendanceRecord(studentId, date);
    }
  }

  // ── CREATE attendance record ──
  async createAttendance(data) {
    try {
      const response = await fetch("http://localhost:5155/api/attendance", {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify(data),
      });

      if (response.ok) {
        return await response.json();
      }
      throw new Error("API error: " + response.status);
    } catch (error) {
      console.log("Saving to localStorage instead");
      return this.saveLocalAttendance(data);
    }
  }

  // ── UPDATE attendance record ──
  async updateAttendance(id, data) {
    try {
      const response = await fetch(
        `http://localhost:5155/api/attendance/${id}`,
        {
          method:  "PUT",
          headers: { "Content-Type": "application/json" },
          body:    JSON.stringify(data),
        }
      );

      if (response.ok) {
        return await response.json();
      }
      throw new Error("API error: " + response.status);
    } catch (error) {
      console.log("Updating localStorage instead");
      return this.updateLocalAttendance(id, data);
    }
  }

  // ── localStorage methods ──

  getLocalAttendance(params = {}) {
    const records = JSON.parse(localStorage.getItem(this.storageKey) || "[]");

    return records.filter(r => {
      // FIX: use String() comparison so number/string mismatch never causes wrong results
      const matchStudent = params.studentId !== undefined
        ? String(r.studentId) === String(params.studentId)
        : true;

      const matchDate = params.date !== undefined
        ? r.date === params.date
        : true;

      // Both conditions must pass (supports filtering by student AND date together)
      return matchStudent && matchDate;
    });
  }

  getLocalAttendanceRecord(studentId, date) {
    const records = JSON.parse(localStorage.getItem(this.storageKey) || "[]");
    return (
      records.find(
        r =>
          String(r.studentId) === String(studentId) &&
          r.date === date
      ) || null
    );
  }

  saveLocalAttendance(data) {
    const records = JSON.parse(localStorage.getItem(this.storageKey) || "[]");
    const newRecord = {
      id: "local_" + Date.now(),
      ...data,
    };
    records.push(newRecord);
    localStorage.setItem(this.storageKey, JSON.stringify(records));
    return newRecord;
  }

  updateLocalAttendance(id, data) {
    const records = JSON.parse(localStorage.getItem(this.storageKey) || "[]");
    const index   = records.findIndex(r => String(r.id) === String(id));

    if (index !== -1) {
      records[index] = { ...records[index], ...data };
      localStorage.setItem(this.storageKey, JSON.stringify(records));
      return records[index];
    }

    return null;
  }
}

const attendanceServiceInstance = new AttendanceService();
export default attendanceServiceInstance;
